  isDarkMode: false,
  activeTab: 'home',
  isTooltipVisible: false,
  isToastVisible: false,
  focusedField: null,
  currentStep: 0,
  openAccordionId: null,
  openDropdownId: null,
  isScrollLocked: false,
  keyboardShortcutsEnabled: true,

  // Local workflows
  wizardProgress: 0,
  searchQuery: '',
  selectedItems: [],
  draftContent: '',
  publishState: 'draft',
  uploadProgress: 0,
  themeVariant: 'system',
  pinnedItemIds: [],
  breadcrumbs: [],
  visibleColumns: [],
  dragItemId: null,

  // Transitions
  pageTransition: 'none',
  isLoading: false,
  animationTrigger: null,
  transitionComplete: false,
  isOverlayVisible: false,

  // Side-effect flags
  localStorageSynced: false,
  userPrefsSynced: false,
  clipboardContent: '',
