export const {
  setGlobalSyncing,
  setLastGlobalSync,
  setSyncError,
  clearSyncError,
  setFeatureSyncStatus,
  clearFeatureSyncStatus,
  enqueueRetry,
  dequeueRetry,
  addSyncJob,
  updateSyncJobStatus,
  clearSyncJobs,
  lockResource,
  unlockResource,
  queueOfflineMutation,
  clearOfflineMutations,
  addConflictResource,
  removeConflictResource,
  setAutoSyncEnabled,
  setSyncRateLimit,
  setSyncIndicatorVisible,
  setSyncMode,
  resetSyncState,
} = syncSlice.actions;

export default syncSlice.reducer;

